-- Synthetic accounts in an isolated database only. Never run in Supabase.
begin;
create function pg_temp.check_true(ok boolean,message text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'ASSERT: %',message;end if;end$$;
select set_config('app.admin_user_update','1',true);
alter table auth.users disable trigger on_auth_user_created;
insert into auth.users(id,email) select ('00000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'ministry-'||i||'@example.invalid' from generate_series(1,8) i;
alter table auth.users enable trigger on_auth_user_created;
insert into public.profiles(id,email,name,status,access_level) select id,email,email,case when right(id::text,1)='8' then 'inactive' else 'active' end,case right(id::text,1) when '1' then 'super_admin' when '2' then 'admin' else 'member' end from auth.users where email like 'ministry-%';
insert into public.profile_worship_roles(profile_id,role_id,is_primary) select '00000000-0000-0000-0000-000000000007',id,true from public.worship_roles where name='Vocalist' limit 1;
insert into public.services(id,title,date,time,end_date,end_time,status,event_kind) values('10000000-0000-0000-0000-000000000001','Synthetic service',current_date+1,'18:00',current_date+1,'20:00','scheduled','service');
insert into public.service_team(service_id,person_id,role,worship_role_id) select '10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000007',name,id from public.worship_roles where name='Vocalist' limit 1;
update public.services set published_at=now(),status='completed' where id='10000000-0000-0000-0000-000000000001';
insert into public.attendance_sessions(id,service_id,name,session_date,session_time,end_time,qr_code) values('30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','Synthetic attendance',current_date+1,'18:00','20:00','synthetic-secret-token');
insert into public.member_stage_appearances(service_id,person_id,played,recorded_by) values('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000008',true,'00000000-0000-0000-0000-000000000001');
insert into public.services(id,title,date,time,end_date,end_time,status,event_kind) values('10000000-0000-0000-0000-000000000002','Response clock service',current_date+2,'18:00',current_date+2,'20:00','scheduled','general_meeting');
insert into public.service_team(service_id,person_id,role,worship_role_id) select '10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000007',name,id from public.worship_roles where name='Vocalist' limit 1;
update public.services set published_at=now() where id='10000000-0000-0000-0000-000000000002';
insert into public.schedule_quarters(starts_on,published_by) values(date_trunc('quarter',current_date+2)::date,'00000000-0000-0000-0000-000000000001');
insert into public.schedule_slots(id,quarter,service_id,role_id,role,person_id,state,source_assignment) select '40000000-0000-0000-0000-000000000001',date_trunc('quarter',current_date+2)::date,t.service_id,t.worship_role_id,t.role,t.person_id,'pending',t.id from public.service_team t where service_id='10000000-0000-0000-0000-000000000002';
insert into public.schedule_attempts(slot_id,person_id,state,replacement) values('40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000007','notified',false);
insert into public.schedule_notifications(recipient,service_id,kind,dedupe_key,created_at) values('00000000-0000-0000-0000-000000000007','10000000-0000-0000-0000-000000000002','assignment','synthetic-clock',now()-interval '5 minutes');
select pg_temp.check_true(public.schedule_eligible('40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000007'),'obsolete weekday availability does not exclude an eligible member');
grant select on public.attendance_sessions to authenticated;
grant select on public.service_team,public.services,public.profiles,public.worship_roles,public.songs,public.setlist_items to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.ministry_set_roles('00000000-0000-0000-0000-000000000003',array['technical_admin']);
select public.ministry_set_roles('00000000-0000-0000-0000-000000000004',array['musical_admin']);
select public.ministry_set_roles('00000000-0000-0000-0000-000000000005',array['pastoral_admin']);
select public.ministry_set_roles('00000000-0000-0000-0000-000000000006',array['worship_leader']);
select public.ministry_save_criterion('{"name":"Timing","name_ar":"التوقيت","audience":"musician","minimum":1,"maximum":5,"weight":1,"display_order":10,"active":true}');
select public.ministry_save_member('{"person_id":"00000000-0000-0000-0000-000000000007","category":"newcomer","serving_status":"active","leader_quote":"Serve faithfully"}');
select pg_temp.check_true((select category='newcomer' from public.ministry_members where person_id='00000000-0000-0000-0000-000000000007'),'metadata saved');
select public.ministry_finalize_setlist('10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true);
select pg_temp.check_true(public.can_evaluate_members(),'technical access');
select public.ministry_save_rating(jsonb_build_object('service_id','10000000-0000-0000-0000-000000000001','person_id','00000000-0000-0000-0000-000000000007','audience','musician','comment','Private synthetic feedback','state','submitted','scores',jsonb_build_array(jsonb_build_object('criterion_id',(select id from public.rating_criteria where name='Timing' and active),'value',4))));
select public.ministry_save_rating(jsonb_build_object('service_id','10000000-0000-0000-0000-000000000001','person_id','00000000-0000-0000-0000-000000000007','audience','musician','comment','Revised private feedback','state','submitted','revision',1,'scores',jsonb_build_array(jsonb_build_object('criterion_id',(select id from public.rating_criteria where name='Timing' and active),'value',5))));
select pg_temp.check_true((select count(*)=1 from public.service_evaluations),'one evaluation');
select pg_temp.check_true((select count(*)=2 from public.evaluation_revisions),'revision history retained');
select public.ministry_record_stage('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000007',true);
select public.ministry_save_criterion(jsonb_build_object('id',(select id from public.rating_criteria where name='Timing' and active),'name','Timing v2','name_ar','التوقيت','audience','musician','minimum',0,'maximum',10,'weight',2,'display_order',10,'active',true));
select pg_temp.check_true((select (scores->0->>'maximum')::integer=5 from public.service_evaluations),'original scale retained');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select pg_temp.check_true(public.has_permission('ratings.musician'),'musical rating permission');
select pg_temp.check_true(not public.can_evaluate_members(),'musical evaluations denied');
select pg_temp.check_true((select count(*)=0 from public.service_evaluations),'musical cannot read evaluations');
select pg_temp.check_true((select count(*)=0 from public.evaluation_revisions),'musical cannot read revisions');
select public.ministry_save_rating(jsonb_build_object('person_id','00000000-0000-0000-0000-000000000007','audience','musician','scores',jsonb_build_array(jsonb_build_object('criterion_id',(select id from public.rating_criteria where name='Timing v2' and active),'value',7))));
do $$begin perform public.ministry_set_roles('00000000-0000-0000-0000-000000000004',array['technical_admin']);raise exception 'self escalation unexpectedly succeeded';exception when insufficient_privilege then null;end$$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000005',true);
select pg_temp.check_true(public.has_permission('reports.view'),'pastoral reports');
select pg_temp.check_true((select count(*)=0 from public.attendance_sessions),'pastoral cannot enumerate QR tokens');
select pg_temp.check_true((select count(*)=1 from public.get_report_attendance_sessions()),'pastoral gets safe session metadata');
select pg_temp.check_true((select not (value?'qr_code') from public.get_report_attendance_sessions() value limit 1),'safe report metadata omits QR token');
select pg_temp.check_true((select count(*)=0 from public.service_evaluations),'pastoral cannot read evaluations');
select pg_temp.check_true((select count(*)=0 from public.member_ratings),'pastoral cannot read private profile ratings');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select pg_temp.check_true(not public.can_evaluate_members(),'ordinary admin evaluation access denied');
select pg_temp.check_true((select count(*)=0 from public.service_evaluations),'ordinary admin cannot read evaluations');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000006',true);
select pg_temp.check_true(public.has_permission('reports.own') and not public.has_permission('reports.view'),'leader scope');
select pg_temp.check_true((select count(*)=0 from public.service_evaluations),'leader cannot read evaluations');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
select pg_temp.check_true((select count(*)=0 from public.service_evaluations),'member cannot read own evaluations');
select public.respond_schedule_assignment('40000000-0000-0000-0000-000000000001',1,'confirmed');
select public.respond_schedule_assignment('40000000-0000-0000-0000-000000000001',1,'confirmed');
select pg_temp.check_true((select count(*)=1 from public.assignment_response_history),'repeat clicks are idempotent');
select pg_temp.check_true((select sent_at is not null and responded_at>=sent_at+interval '4 minutes' from public.assignment_response_history limit 1),'response starts at actual notification time');
select public.respond_schedule_assignment('40000000-0000-0000-0000-000000000001',2,'declined');
select pg_temp.check_true((select count(*)=2 from public.assignment_response_history),'changed answers retain response history');
do $$begin insert into public.ministry_access_roles values(auth.uid(),'technical_admin',now());raise exception 'direct escalation unexpectedly succeeded';exception when insufficient_privilege then null;end$$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000008',true);
select pg_temp.check_true(not public.has_permission('reports.view') and not public.can_evaluate_members(),'inactive denied');
select pg_temp.check_true((select count(*)=0 from public.member_stage_appearances),'inactive cannot read appearances');
set local role anon;
do $$begin perform * from public.service_evaluations;raise exception 'anonymous read unexpectedly succeeded';exception when insufficient_privilege then null;end$$;
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
set local role authenticated;
-- Song save is one transaction for content, origin year, and canonical tags.
select public.save_song_with_metadata('{"p_title":"Synthetic Song","p_title_ar":"ترنيمة اختبار","p_author":"QA","p_key":"C","p_bpm":72,"p_time_signature":"4/4","p_language":"both","p_themes":["Praise","praise"],"p_sequence":[],"p_notes":"","p_ccli_number":"","p_lyrics":"Line","p_lyrics_sections":[],"p_pro_chords":"C","origin_year":2020}');
select pg_temp.check_true((select origin_year=2020 and cardinality(themes)=1 from public.songs where title='Synthetic Song'),'song year and canonical tags persist');
select public.ministry_manage_tag((select id from public.song_tag_catalog where lower(name)='praise'),'Worship',true);
select pg_temp.check_true((select themes=array['Worship'] from public.songs where title='Synthetic Song'),'tag rename updates song links');
-- A later invalid bulk-import row must roll back earlier valid rows.
do $$declare before_count integer;begin
 select count(*) into before_count from public.services;
 begin
 perform public.ministry_bulk_schedule(jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'title','Atomic good row','date',current_date+3,'time','18:00','end_date',current_date+3,'end_time','20:00','event_kind','general_meeting','team','[]'::jsonb),jsonb_build_object('id',gen_random_uuid(),'title','Atomic bad row','date',current_date+3,'time','18:00','end_date',current_date+3,'end_time','17:00','event_kind','general_meeting','team','[]'::jsonb)));
 raise exception 'invalid import unexpectedly succeeded';
 exception when others then if sqlerrm='invalid import unexpectedly succeeded' then raise;end if;end;
 perform pg_temp.check_true((select count(*)=before_count from public.services),'bulk import is atomic');
end$$;
select public.ministry_save_guest('{"name":"Synthetic Guest","roles":["Keys"],"status":"active"}');
select pg_temp.check_true((select count(*)=0 from public.profiles where name='Synthetic Guest'),'guest has no sign-in profile');
-- Published reporting metadata stays editable while schedule fields remain locked.
select public.ministry_save_subcategory('10000000-0000-0000-0000-000000000001','Evening shift');
select pg_temp.check_true((select subcategory='Evening shift' from public.services where id='10000000-0000-0000-0000-000000000001'),'published subcategory saves');
reset role;
rollback;
